function stairHeight(s,x,z){const localX=x-s.sx,localZ=z-s.sz;if(localZ<=s.landing)return P.storey/2;const t=Math.max(0,Math.min(1,(localZ-s.landing)/s.run));return localX<s.w/2?(1-t)*P.storey/2:P.storey/2+t*P.storey/2;}
function insideStair(s,x,z){return x>s.sx+.055&&x<s.sx+s.w-.055&&z>s.sz+.055&&z<s.sz+s.d;}
function candidateFeet(x,z){const s=stairModels.find(s=>insideStair(s,x,z));if(s){const h=stairHeight(s,x,z);if(Math.abs(h-feet)<.38)return{feet:h,stair:s};return null;}if(stairActive){const s=stairActive;if(z>=s.sz+s.d-.03){const right=x>s.sx+s.w/2;const end=right?P.storey:0;if(Math.abs(feet-end)<.38)return{feet:end,stair:null};}return null;}return{feet:level*P.storey,stair:null};}
function canMove(x,z,height=feet,ignoreDoors=false){const px=x/P.scale+715,py=z/P.scale+360,r=.22;if(!ignoreDoors&&height<.4&&!gate.userData.open&&Math.abs(x-X(1380))<r+.12&&py>180-r/P.scale&&py<270+r/P.scale)return false;if(height<.4&&surroundings.onRoad(px,py,r/P.scale))return false;if(!(inOutline(px,py)||isCourt(px,py)||(height<.4&&surroundings.isSafe(px,py))))return false;if(height>2&& !inOutline(px,py))return false;
 for(const c of colliders){if(height+.18>=c.y2||height+1.6<=c.y1)continue;if(x+r>c.x1&&x-r<c.x2&&z+r>c.z1&&z-r<c.z2)return false;}
 if(!ignoreDoors)for(const d of doors){if(Math.abs(height-d.base)>1)continue;for(const leaf of d.leaves){leaf.hinge.updateWorldMatrix(true,false);const v=leaf.hinge.worldToLocal(new T.Vector3(x,height+1,z));const low=leaf.sign>0?0:-leaf.span,high=leaf.sign>0?leaf.span:0;if(v.x>low-r&&v.x<high+r&&Math.abs(v.z)<r+.035)return false;}}
 return true;}
function warnRoad(){roadWarningTime=2.8;const el=document.querySelector('#roadWarning');if(el.style.display!=='block')el.textContent='C’est dangereux ! Tu ne peux pas aller sur la route. Utilise le passage piéton pour rejoindre le gymnase.';el.style.display='block';}
function move(dx,dz){for(const [mx,mz]of [[dx,0],[0,dz]]){if(!mx&&!mz)continue;const x=camera.position.x+mx,z=camera.position.z+mz,next=candidateFeet(x,z);if(next&&canMove(x,z,next.feet)){camera.position.x=x;camera.position.z=z;feet=next.feet;stairActive=next.stair;if(!stairActive)level=feet>P.storey/2?1:0;}else if(next&&next.feet<.4&&surroundings.onRoad(x/P.scale+715,z/P.scale+360,.22/P.scale))warnRoad();}camera.position.y=feet+eye;}
function nearestDoor(){let best=null,distance=2.4;for(const d of doors){if(Math.abs(feet-d.base)>.7)continue;const range=Math.hypot(camera.position.x-d.x,camera.position.z-d.z);if(range<distance){distance=range;best=d;}}return best;}
function interact(){const d=nearestDoor();if(d){d.open=!d.open;}}
let locked=false,drag=false,lastX=0,lastY=0;const look=()=>{if(overview)document.querySelector('#overview').click();renderer.domElement.requestPointerLock?.();};document.querySelector('#look').onclick=look;renderer.domElement.addEventListener('click',()=>{if(!mapOpen&&!overview)look();});document.addEventListener('pointerlockchange',()=>{locked=document.pointerLockElement===renderer.domElement;held.clear();document.querySelector('#look').style.display=locked?'none':'block';});
function rotate(dx,dy){if(overview)return;yaw-=dx*.0021;pitch=Math.max(-1.25,Math.min(1.25,pitch-dy*.0018));camera.rotation.set(pitch,yaw,0);}
document.addEventListener('mousemove',e=>{if(locked)rotate(e.movementX,e.movementY);});renderer.domElement.addEventListener('pointerdown',e=>{if(!locked){drag=true;lastX=e.clientX;lastY=e.clientY;}});document.addEventListener('pointermove',e=>{if(drag&&!locked){rotate(e.clientX-lastX,e.clientY-lastY);lastX=e.clientX;lastY=e.clientY;}});document.addEventListener('pointerup',()=>drag=false);
function drawMap(){drawCampusMap(document.querySelector('#drawing'),mapLevel,(mapLevel===(feet>1.8?1:0))?pixels():null);document.querySelector('#ground').classList.toggle('active',mapLevel===0);document.querySelector('#upper').classList.toggle('active',mapLevel===1);}
function toggleMap(){mapOpen=!mapOpen;document.querySelector('#map').classList.toggle('open',mapOpen);held.clear();if(mapOpen){document.exitPointerLock?.();mapLevel=feet>1.8?1:0;drawMap();}}
document.querySelector('#mapButton').onclick=toggleMap;document.querySelector('#mapClose').onclick=toggleMap;document.querySelector('#ground').onclick=()=>{mapLevel=0;drawMap();};document.querySelector('#upper').onclick=()=>{mapLevel=1;drawMap();};
let savedView=null;document.querySelector('#overview').onclick=()=>{document.exitPointerLock?.();held.clear();overview=!overview;if(overview){savedView={p:camera.position.clone(),yaw,pitch};camera.position.set(47,43,-40);camera.lookAt(0,1,0);}else{camera.position.copy(savedView.p);yaw=savedView.yaw;pitch=savedView.pitch;camera.rotation.set(pitch,yaw,0);}document.querySelector('#overview').textContent=overview?'Retour à pied':'Vue d’ensemble';};
document.addEventListener('keydown',e=>{const key=e.key.toLowerCase();if(['z','q','s','d','w','a','arrowup','arrowdown','arrowleft','arrowright','shift'].includes(key)){e.preventDefault();held.add(key);}if(key==='e'&&!e.repeat&&!mapOpen)interact();if(key==='m'&&!e.repeat)toggleMap();});document.addEventListener('keyup',e=>held.delete(e.key.toLowerCase()));addEventListener('blur',()=>held.clear());
for(const button of document.querySelectorAll('#touch button')){button.addEventListener('pointerdown',e=>{e.preventDefault();if(button.dataset.key==='e')interact();else held.add(button.dataset.key);button.setPointerCapture(e.pointerId);});for(const event of ['pointerup','pointercancel'])button.addEventListener(event,()=>held.delete(button.dataset.key));}
camera.position.set(X(1150),eye,Z(220));camera.rotation.set(pitch,yaw,0);const clock=new T.Clock();
function animate(){requestAnimationFrame(animate);const dt=Math.min(clock.getDelta(),.04);if(roadWarningTime>0){roadWarningTime=Math.max(0,roadWarningTime-dt);if(!roadWarningTime)document.querySelector('#roadWarning').style.display='none';}for(const d of doors)for(const leaf of d.leaves)leaf.hinge.rotation.y+=((d.open?leaf.target:0)-leaf.hinge.rotation.y)*Math.min(1,dt*7);window.campusDay?.tick(dt,mapOpen||overview);if(!mapOpen&&!overview&&!window.campusDay?.dialogOpen){let f=Number(held.has('z')||held.has('w')||held.has('arrowup'))-Number(held.has('s')||held.has('arrowdown')),s=Number(held.has('d')||held.has('arrowright'))-Number(held.has('q')||held.has('a')||held.has('arrowleft'));const norm=Math.hypot(f,s)||1,speed=(held.has('shift')?4.6:2.6)*dt;move((-Math.sin(yaw)*f+Math.cos(yaw)*s)/norm*speed,(-Math.cos(yaw)*f-Math.sin(yaw)*s)/norm*speed);const d=nearestDoor(),prompt=document.querySelector('#prompt');prompt.style.display=d?'block':'none';if(d)prompt.textContent='E · '+(d.open?'Fermer':'Ouvrir')+' · '+d.name;const pos=pixels(),room=P.floors[level].rooms.find(r=>P.containsRoom(r,pos.x,pos.y));document.querySelector('#place').textContent=stairActive?'Escalier '+stairActive.id:room?room.name+' · '+(level?'Étage':'RDC'):isCourt(pos.x,pos.y)?'Cour du collège':surroundings.isSafe(pos.x,pos.y)?(pos.x>=2180?'Gymnase · Collège Douggy':pos.x>=1780?'Accès au gymnase':pos.x>=1640?'Passage piéton':pos.x>=1380&&pos.y>=140&&pos.y<=340?'Place devant le collège':'Trottoir · collège'):level?'Petit hall / circulation · Étage':'Grand hall / circulation · RDC';}renderer.render(scene,camera);}
