window.campusDebug={plan:P,scene,camera,renderer,doors,colliders,stairModels,lockers,roomColors,glazedWindows,floorFinishes,slabFinishes,paintCoverage,surroundings,furnishings,canMove,stairHeight,move,gateOpen:()=>gate.userData.open,setGateOpen(open){gate.userData.open=open;gate.position.z=Z(open?90:225);},position:()=>({feet,level,stair:stairActive?.id,...pixels()}),teleport(px,py,l=0){level=l;feet=l*P.storey;stairActive=null;camera.position.set(X(px),feet+eye,Z(py));},overview(){document.querySelector('#overview').click();}};
